attestation_envelope_v6_schema: dict[str, Any] = {
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/attestation-envelope-v6.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": False,
    "description": "RFC-0042 §Design Layer 4 — per-PR proof bundle. Carries per-reviewer transcript hashes, per-leaf "
    "Merkle inclusion proofs, the operator-signed root, and the PR-bound nonce. Replaces v5 envelopes "
    "(contentHashV3/V4/V5) during RFC-0042 Phase 2.",
    "properties": {
        "leafCount": {
            "description": "Total number of leaves in the tree at sign time. Required by "
            "verifyInclusion to reject out-of-bounds leafIndex (CVE-2012-2459 "
            "second-preimage mitigation).",
            "minimum": 1,
            "type": "integer",
        },
        "merkleProofs": {
            "description": "Per-leaf RFC-6962 Merkle inclusion proofs. Each proof is a "
            "sibling-hash path from leaf level to (but not including) the root.",
            "items": {
                "additionalProperties": False,
                "properties": {
                    "leafIndex": {
                        "description": "0-based position of the leaf this proof attests to.",
                        "minimum": 0,
                        "type": "integer",
                    },
                    "proof": {
                        "description": "Ordered list of sibling SHA-256 "
                        "hashes from leaf level to root.",
                        "items": {"pattern": "^[0-9a-f]{64}$", "type": "string"},
                        "type": "array",
                    },
                },
                "required": ["leafIndex", "proof"],
                "type": "object",
            },
            "type": "array",
        },
        "nonce": {
            "description": "32-byte hex nonce bound to the PR's head SHA (replay protection). Derived "
            "from SHA-256(headSha || random) per RFC-0042 §Nonce binding (OQ-6).",
            "pattern": "^[0-9a-f]{64}$",
            "type": "string",
        },
        "rootHash": {
            "description": "SHA-256 Merkle root over all leaves in .ai-sdlc/transcript-leaves.jsonl "
            "at sign time.",
            "pattern": "^[0-9a-f]{64}$",
            "type": "string",
        },
        "rootSignature": {
            "description": "Operator ed25519 signature over rootHash (base64-encoded). Verified "
            "against any key in .ai-sdlc/trusted-reviewers.yaml (any-of-N per "
            "OQ-4).",
            "minLength": 1,
            "type": "string",
        },
        "schemaVersion": {
            "description": "Schema version — always 'v6' for this schema.",
            "enum": ["v6"],
            "type": "string",
        },
        "signedAt": {
            "description": "ISO-8601 UTC timestamp when this envelope was signed.",
            "format": "date-time",
            "type": "string",
        },
        "signerIdentity": {
            "description": "Free-form identity string of the key holder who signed (typically "
            "email:hostname). Informational; not verified.",
            "type": "string",
        },
        "subject": {
            "additionalProperties": False,
            "description": "The Git commit this envelope attests to.",
            "properties": {
                "digest": {
                    "additionalProperties": False,
                    "properties": {
                        "sha1": {
                            "description": "Git commit SHA (40 hex "
                            "chars) this envelope is "
                            "bound to.",
                            "pattern": "^[0-9a-f]{40}$",
                            "type": "string",
                        }
                    },
                    "required": ["sha1"],
                    "type": "object",
                }
            },
            "required": ["digest"],
            "type": "object",
        },
        "transcriptLeaves": {
            "description": "Summary of each reviewer's transcript leaf included in this PR's "
            "proof bundle.",
            "items": {
                "additionalProperties": False,
                "properties": {
                    "anchorEvidence": {
                        "additionalProperties": False,
                        "description": "RFC-0047 Phase 2 "
                        "(AISDLC-594) "
                        "audit-only CI "
                        "provenance evidence "
                        "bound into this leaf. "
                        "NOT the security "
                        "anchor — the ci-only "
                        "root signature is. "
                        "Absent when no "
                        "genuine anchor "
                        "evidence exists.",
                        "properties": {
                            "runId": {
                                "description": "CI run identifier (e.g. GitHub Actions run_id).",
                                "minLength": 1,
                                "type": "string",
                            },
                            "signerKeyId": {
                                "description": "Identifier "
                                "of "
                                "the "
                                "ci-only "
                                "signing "
                                "key "
                                "used "
                                "to "
                                "sign "
                                "the "
                                "Merkle "
                                "root.",
                                "minLength": 1,
                                "type": "string",
                            },
                            "workflowRef": {
                                "description": "CI "
                                "workflow "
                                "reference "
                                "(e.g. "
                                "owner/repo/.github/workflows/x.yml@refs/heads/main).",
                                "minLength": 1,
                                "type": "string",
                            },
                        },
                        "required": ["runId", "workflowRef", "signerKeyId"],
                        "type": "object",
                    },
                    "harnessTranscriptHash": {
                        "description": "AISDLC-570 "
                        "sign-time-only "
                        "harness-captured "
                        "transcript "
                        "hash. `null` "
                        "when no "
                        "harness signal "
                        "existed for "
                        "this leaf.",
                        "pattern": "^[0-9a-f]{64}$",
                        "type": ["string", "null"],
                    },
                    "independenceTier": {
                        "description": "RFC-0046 Phase 1 "
                        "(AISDLC-588) "
                        "independence tier "
                        "for this leaf. "
                        "Absent on legacy "
                        "leaves — verifier "
                        "falls back to "
                        "verdictClass via "
                        "dual-read.",
                        "enum": ["none", "attested", "isolated"],
                        "type": "string",
                    },
                    "leafIndex": {
                        "description": "0-based sequential "
                        "position in "
                        ".ai-sdlc/transcript-leaves.jsonl.",
                        "minimum": 0,
                        "type": "integer",
                    },
                    "reviewerName": {
                        "description": "Reviewer subagent role "
                        "(e.g. 'code-reviewer', "
                        "'test-reviewer', "
                        "'security-reviewer').",
                        "minLength": 1,
                        "type": "string",
                    },
                    "stage": {
                        "description": "Staged review stage that "
                        "produced this leaf. Absent on "
                        "every other leaf; never null "
                        "or empty.",
                        "enum": ["plan", "execute", "synthesize"],
                        "type": "string",
                    },
                    "transcriptHash": {
                        "description": "SHA-256 hex of the raw reviewer transcript JSONL file.",
                        "pattern": "^[0-9a-f]{64}$",
                        "type": "string",
                    },
                    "verdictClass": {
                        "description": "AISDLC-568 trust class "
                        "for this leaf. FROZEN / "
                        "legacy-read as of "
                        "RFC-0046 (AISDLC-588) — "
                        "superseded by "
                        "independenceTier.",
                        "enum": ["independent", "self-authored"],
                        "type": "string",
                    },
                },
                "required": ["leafIndex", "reviewerName", "transcriptHash"],
                "type": "object",
            },
            "type": "array",
        },
        "workflowDigest": {
            "additionalProperties": False,
            "description": "RFC-0056 phase 3 (OQ-4). Present when the workflow engine ran: "
            "which Workflow document drove the run. The verifier recomputes "
            "sha256 from `git show <baseSha>:<path>` (a `builtin:` path must "
            "find no document at baseSha) and refuses an envelope whose run "
            "state shows engine records but no digest. Absent on every envelope "
            "signed without the engine; those verify unchanged.",
            "properties": {
                "baseSha": {
                    "description": "Base-branch commit the document was read from.",
                    "pattern": "^[0-9a-f]{40}$",
                    "type": "string",
                },
                "path": {
                    "description": "Repo path of the document "
                    "(`.ai-sdlc/workflow.yaml`), or "
                    "`builtin:execute-task` when the base branch "
                    "has none and the plugin default ran.",
                    "minLength": 1,
                    "type": "string",
                },
                "sha256": {
                    "description": "SHA-256 hex of the document text as committed at baseSha.",
                    "pattern": "^[0-9a-f]{64}$",
                    "type": "string",
                },
            },
            "required": ["path", "sha256", "baseSha"],
            "type": "object",
        },
    },
    "required": [
        "schemaVersion",
        "subject",
        "transcriptLeaves",
        "merkleProofs",
        "rootHash",
        "rootSignature",
        "nonce",
        "leafCount",
        "signedAt",
    ],
    "title": "AttestationEnvelopeV6",
    "type": "object",
}

audit_ignores_schema: dict[str, Any] = {
    "$defs": {
        "AuditIgnoreEntry": {
            "additionalProperties": False,
            "description": "A single CVE exemption. All three fields are required — there is no "
            "open-ended waiver.",
            "properties": {
                "cveId": {
                    "description": "The CVE identifier (e.g. 'CVE-2024-12345') or "
                    "GHSA identifier (e.g. 'GHSA-xxxx-yyyy-zzzz') "
                    "as reported by `pnpm audit`. Must be an exact "
                    "match to the advisory ID in the audit output.",
                    "examples": ["CVE-2024-12345", "GHSA-4jqc-xw3x-m5hv"],
                    "pattern": "^(CVE-\\d{4}-\\d{4,}|GHSA-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4})$",
                    "type": "string",
                },
                "expiresAt": {
                    "description": "ISO 8601 date (YYYY-MM-DD) or datetime "
                    "(YYYY-MM-DDTHH:MM:SSZ) after which this "
                    "exemption is no longer valid. The gate "
                    "treats expired entries as absent — i.e., "
                    "the advisory is no longer ignored. Must "
                    "be in the future at creation time; "
                    "recommended renewal cadence is 30-90 "
                    "days.",
                    "examples": ["2026-08-13T00:00:00Z", "2026-06-01T00:00:00Z"],
                    "format": "date-time",
                    "type": "string",
                },
                "justification": {
                    "description": "Human-readable reason why this "
                    "advisory is being exempted. Should "
                    "include: (1) why no upstream fix is "
                    "available or applicable, (2) any "
                    "compensating controls in place, and "
                    "(3) who approved the exemption.",
                    "examples": [
                        "No fix available in dependency-xyz as "
                        "of 2026-05-13. Attack vector requires "
                        "direct filesystem access which is "
                        "blocked by our sandbox policy. Approved "
                        "by @security-lead."
                    ],
                    "minLength": 20,
                    "type": "string",
                },
            },
            "required": ["cveId", "justification", "expiresAt"],
            "title": "Audit Ignore Entry",
            "type": "object",
        }
    },
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/audit-ignores.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "description": "Per-CVE time-bound exemption list for the pre-push audit gate. Place this file at .audit-ignores.json "
    "in your repo root. Each entry allows scripts/audit-with-ignores.mjs to suppress a specific advisory "
    "until expiresAt; after that date the entry is treated as if it does not exist and the gate fails as "
    "normal.",
    "items": {"$ref": "#/$defs/AuditIgnoreEntry"},
    "title": "AI-SDLC Audit Ignores",
    "type": "array",
}

