vector_store_entry.v1_schema: dict[str, Any] = {
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/vector-store-entry.v1.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": False,
    "description": "JSON Schema for the VectorStoreEntry shape per RFC-0019 §8.1. Defines the format of each line in the "
    "JSONL embedding storage backend files at <artifactsDir>/_embeddings/<provider>-<modelVersion>.jsonl.",
    "properties": {
        "embeddingModelVersion": {
            "description": "adapter.modelVersion at write time (e.g., '2024-01-25'). "
            "Together with embeddingProvider, forms the provenance "
            "identity of this vector. Allows migration tooling "
            "(cli-embedding-bump) to detect stale vectors from retired "
            "snapshots.",
            "minLength": 1,
            "type": "string",
        },
        "embeddingProvider": {
            "description": "adapter.name at write time (e.g., "
            "'openai-text-embedding-3-small'). Together with "
            "embeddingModelVersion, forms the provenance identity of this "
            "vector. Vectors from different providers are NOT "
            "interchangeable.",
            "minLength": 1,
            "type": "string",
        },
        "metadata": {
            "additionalProperties": True,
            "description": "Adopter-defined metadata. Examples: {sourceDoc: 'rfc-0009.md', shardId: "
            "'OQ-6'}, {consumerLabel: 'rfc-0009-tessellation-drift'}. Opaque to the "
            "framework.",
            "type": "object",
        },
        "text": {
            "description": "Original source text. REQUIRED — needed for re-embedding during migration "
            "(cli-embedding-bump). Adopters with privacy concerns MAY store text in a "
            "separate encrypted store and reference it by textHash.",
            "minLength": 1,
            "type": "string",
        },
        "textHash": {
            "description": "SHA-256 hex digest of the source text. Used as a read-side cache key "
            "('have we already embedded this exact text?') and for content-addressable "
            "storage lookup. Recomputing on every lookup is wasteful; storing "
            "separately avoids that.",
            "pattern": "^[0-9a-f]{64}$",
            "type": "string",
        },
        "vector": {
            "description": "The embedding vector. Length MUST equal the adapter's declared dimensions "
            "at write time.",
            "items": {"type": "number"},
            "minItems": 1,
            "type": "array",
        },
        "writtenAt": {
            "description": "ISO 8601 timestamp of when this entry was written. Used by "
            "cli-embedding-gc for mtime-based retention.",
            "format": "date-time",
            "type": "string",
        },
    },
    "required": [
        "vector",
        "embeddingProvider",
        "embeddingModelVersion",
        "writtenAt",
        "text",
        "textHash",
    ],
    "title": "VectorStoreEntry",
    "type": "object",
}

work_item_schema: dict[str, Any] = {
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/work-item.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": True,
    "description": "A backlog work item with optional soul and variant targeting for admission scoring. Implements "
    "RFC-0009 §5.3 targetedSouls and RFC-0017 §5.4 targetedVariants.",
    "properties": {
        "description": {"description": "Optional longer description.", "type": "string"},
        "id": {
            "description": "Canonical work item identifier (e.g. AISDLC-313).",
            "minLength": 1,
            "type": "string",
        },
        "labels": {
            "description": "Classification labels.",
            "items": {"type": "string"},
            "type": "array",
        },
        "targetedJourneys": {
            "description": "Journey references this work item targets per RFC-0018 §5.4 / "
            "§6.1. When non-empty, admission scoring routes Sα₂ + Cκ + Eρ₅ "
            "through journey-level design intent + success metrics. Two URI "
            "forms: soul-scoped '<soul-id>/<journey-id>' or variant-scoped "
            "'<soul-id>/<variant-id>/<journey-id>'. Empty or absent = "
            "soul/variant-aggregate scoring (backward-compatible with RFC-0009 "
            "+ RFC-0017 baseline).",
            "items": {
                "description": "Path-style journey URI per RFC-0018 §6.1: "
                "'<soul-id>/<journey-id>' (soul-scoped) OR "
                "'<soul-id>/<variant-id>/<journey-id>' (variant-scoped). "
                "All segments are kebab-case. Examples: "
                "'spry-engage/onboarding', "
                "'spry-engage/annual-test/backflow-submit'.",
                "pattern": "^[a-z][a-z0-9-]*/([a-z][a-z0-9-]*/)?[a-z][a-z0-9-]*$",
                "type": "string",
            },
            "type": "array",
        },
        "targetedSouls": {
            "description": "Soul DID URIs this work item explicitly targets per RFC-0009 §5.3 "
            "(targetedSouls field). Drives soul-scope admission scoring. Empty = "
            "substrate-only (min-over-all-souls degenerate case per RFC-0009 §6).",
            "items": {
                "description": "Soul DID URI (e.g. 'did:platform-x:soul:spry-engage') or "
                "soul slug (e.g. 'spry-engage').",
                "type": "string",
            },
            "type": "array",
        },
        "targetedVariants": {
            "description": "Variant references this work item targets per RFC-0017 §5.4. Each "
            "entry is a path-style URI in the format "
            "'did:{method}:{platform}:soul:{soul-id}/variant:{variant-id}' "
            "(OQ-6 resolution). When non-empty, admission scoring routes Sα₁ + "
            "Sα₂ through variant-scoped fields instead of soul-aggregate. "
            "Empty or absent = soul-aggregate scoring (backward-compatible "
            "with RFC-0009 baseline).",
            "items": {
                "description": "Path-style variant URI per RFC-0017 OQ-6: "
                "'did:{method}:{platform}:soul:{soul-id}/variant:{variant-id}'. "
                "The explicit 'variant:' keyword preserves the "
                "parent/child hierarchy and composes with future "
                "RFC-0018 Journey partition types.",
                "pattern": "^did(?::[^:]+)+:soul:[a-z][a-z0-9-]*/variant:[a-z][a-z0-9-]*$",
                "type": "string",
            },
            "type": "array",
        },
        "title": {
            "description": "Human-readable title for the work item.",
            "minLength": 1,
            "type": "string",
        },
    },
    "required": ["id", "title"],
    "title": "AI-SDLC WorkItem",
    "type": "object",
}

workflow_schema: dict[str, Any] = {
    "$defs": {
        "agentNode": {
            "additionalProperties": False,
            "properties": {
                "budget": {"$ref": "#/$defs/budget"},
                "fresh": {"default": False, "type": "boolean"},
                "frozen": {"$ref": "#/$defs/frozen"},
                "gating": {
                    "default": True,
                    "description": "Whether this agent's verdict gates the run.",
                    "type": "boolean",
                },
                "kind": {"const": "agent"},
                "role": {"minLength": 1, "type": "string"},
                "sample": {
                    "default": 1,
                    "description": "Run the node on one PR in N (RFC-0056 OQ-1): the "
                    "integer N, or the string 1/N. The engine skips the "
                    "node, and records the skip, on a PR whose number is "
                    "not a multiple of N. Default 1 (every PR).",
                    "oneOf": [
                        {"minimum": 1, "type": "integer"},
                        {"pattern": "^1/[1-9][0-9]*$", "type": "string"},
                    ],
                },
                "with": {"$ref": "#/$defs/with"},
            },
            "required": ["kind", "role"],
            "type": "object",
        },
        "anchorNode": {
            "additionalProperties": False,
            "properties": {
                "frozen": {"$ref": "#/$defs/frozen"},
                "impl": {
                    "description": "A deterministic implementation id. An agent role is "
                    "not a valid anchor.",
                    "minLength": 1,
                    "not": {
                        "enum": [
                            "developer",
                            "code-reviewer",
                            "test-reviewer",
                            "security-reviewer",
                            "code-reviewer-codex",
                            "test-reviewer-codex",
                            "review-executor",
                        ]
                    },
                    "type": "string",
                },
                "kind": {"const": "anchor"},
                "with": {"$ref": "#/$defs/with"},
            },
            "required": ["kind", "impl"],
            "type": "object",
        },
        "budget": {
            "additionalProperties": False,
            "properties": {
                "maxTokens": {"minimum": 1, "type": "integer"},
                "maxTurns": {"minimum": 1, "type": "integer"},
                "maxUsd": {"exclusiveMinimum": 0, "type": "number"},
            },
            "type": "object",
        },
        "edge": {
            "oneOf": [
                {"pattern": "^\\s*[A-Za-z0-9_-]+\\s*->\\s*[A-Za-z0-9_-]+\\s*$", "type": "string"},
                {
                    "additionalProperties": False,
                    "properties": {
                        "from": {"minLength": 1, "type": "string"},
                        "loop": {
                            "additionalProperties": False,
                            "properties": {"max": {"minimum": 1, "type": "integer"}},
                            "required": ["max"],
                            "type": "object",
                        },
                        "to": {"minLength": 1, "type": "string"},
                        "when": {
                            "description": "Policy expression (@ai-sdlc/reference "
                            "createSimpleExpressionEvaluator grammar).",
                            "minLength": 1,
                            "type": "string",
                        },
                    },
                    "required": ["from", "to"],
                    "type": "object",
                },
            ]
        },
        "fanoutNode": {
            "additionalProperties": False,
            "properties": {
                "cap": {"minimum": 1, "type": "integer"},
                "expect": {
                    "default": "all",
                    "description": "all | n | quorum(k).",
                    "pattern": "^(all|[0-9]+|quorum\\([0-9]+\\))$",
                    "type": "string",
                },
                "frozen": {"$ref": "#/$defs/frozen"},
                "kind": {"const": "fanout"},
                "node": {"$ref": "#/$defs/agentNode"},
                "over": {"minLength": 1, "type": "string"},
                "with": {"$ref": "#/$defs/with"},
            },
            "required": ["kind", "over", "cap", "node"],
            "type": "object",
        },
        "frozen": {
            "description": "A node boolean, or a list of named freeze rules.",
            "oneOf": [
                {"type": "boolean"},
                {"items": {"minLength": 1, "type": "string"}, "minItems": 1, "type": "array"},
            ],
        },
        "humanNode": {
            "additionalProperties": False,
            "properties": {
                "frozen": {"$ref": "#/$defs/frozen"},
                "kind": {"const": "human"},
                "prompt": {"type": "string"},
                "with": {"$ref": "#/$defs/with"},
            },
            "required": ["kind"],
            "type": "object",
        },
        "node": {
            "oneOf": [
                {"$ref": "#/$defs/stepNode"},
                {"$ref": "#/$defs/agentNode"},
                {"$ref": "#/$defs/anchorNode"},
                {"$ref": "#/$defs/fanoutNode"},
                {"$ref": "#/$defs/humanNode"},
            ]
        },
        "stepNode": {
            "additionalProperties": False,
            "properties": {
                "frozen": {"$ref": "#/$defs/frozen"},
                "impl": {"minLength": 1, "type": "string"},
                "inputs": {"type": "string"},
                "kind": {"const": "step"},
                "outputs": {"type": "string"},
                "with": {"$ref": "#/$defs/with"},
            },
            "required": ["kind", "impl"],
            "type": "object",
        },
        "with": {
            "description": "Node knobs read by the engine (for example `lenses` on the review plan node). Open "
            "knobs only; a frozen rule has no key here.",
            "type": "object",
        },
    },
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/workflow.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": False,
    "description": "A composable workflow graph (RFC-0056): typed nodes joined by edges. Phase 2 defines the document and "
    "its validator only; nothing reads it at run time yet. Every `when` is written in the "
    "@ai-sdlc/reference policy expression grammar (createSimpleExpressionEvaluator): comparisons (==, !=, "
    ">, >=, <, <=), &&, ||, !, dotted paths, `contains` and literals. A `when` may only name identifiers "
    "that an upstream node declares as an output.",
    "properties": {
        "apiVersion": {"const": "ai-sdlc.io/v1alpha1"},
        "kind": {"const": "Workflow"},
        "metadata": {
            "additionalProperties": False,
            "properties": {
                "decisions": {
                    "description": "Decision ids that authorize touching a "
                    "frozen node. Each must resolve in the "
                    "catalog on the base branch.",
                    "items": {"pattern": "^DEC-[0-9]+$", "type": "string"},
                    "type": "array",
                },
                "extends": {
                    "description": "Name of the Workflow document this one "
                    "extends, `ai-sdlc/execute-task@<version>`. The "
                    "plugin default is resolved and this document "
                    "is applied as an overlay (RFC-0056 phase 4).",
                    "type": "string",
                },
                "name": {"minLength": 1, "type": "string"},
            },
            "required": ["name"],
            "type": "object",
        },
        "spec": {
            "additionalProperties": False,
            "properties": {
                "anchors": {
                    "description": "Node ids whose deterministic result an agent cannot override.",
                    "items": {"type": "string"},
                    "type": "array",
                },
                "budget": {"$ref": "#/$defs/budget"},
                "edges": {"items": {"$ref": "#/$defs/edge"}, "type": "array"},
                "nodes": {
                    "additionalProperties": {"$ref": "#/$defs/node"},
                    "minProperties": 1,
                    "type": "object",
                },
                "remove": {
                    "description": "Overlay only: node ids removed from the extended "
                    "document. A frozen node cannot be removed.",
                    "items": {"type": "string"},
                    "type": "array",
                },
            },
            "required": ["nodes", "edges"],
            "type": "object",
        },
    },
    "required": ["apiVersion", "kind", "metadata", "spec"],
    "title": "AI-SDLC Workflow",
    "type": "object",
}

worktree_pool_schema: dict[str, Any] = {
    "$id": "https://ai-sdlc.io/schemas/v1alpha1/worktree-pool.schema.json",
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "additionalProperties": False,
    "description": "Declares a pool of git worktrees used by a parallel-execution pipeline (RFC-0010 §6.2 / §7).",
    "properties": {
        "apiVersion": {"$ref": "common.schema.json#/$defs/apiVersion"},
        "kind": {"const": "WorktreePool", "type": "string"},
        "metadata": {"$ref": "common.schema.json#/$defs/metadata"},
        "spec": {
            "additionalProperties": False,
            "properties": {
                "basePort": {
                    "default": 3190,
                    "description": "Base port used by the deterministic port "
                    "allocator (RFC-0010 §8).",
                    "maximum": 65000,
                    "minimum": 1024,
                    "type": "integer",
                },
                "cleanup": {
                    "additionalProperties": False,
                    "description": "Worktree reclamation triggers.",
                    "properties": {
                        "onAbort": {"default": True, "type": "boolean"},
                        "onMerge": {"default": True, "type": "boolean"},
                        "onTimeout": {"default": True, "type": "boolean"},
                    },
                    "type": "object",
                },
                "databaseBranchPools": {
                    "description": "References to DatabaseBranchPool "
                    "resources by name (RFC-0010 §6.7).",
                    "items": {"type": "string"},
                    "type": "array",
                },
                "layout": {
                    "default": "workspace-scoped",
                    "description": "Where worktrees live relative to the clone "
                    "(repo-local) or in a global workspace directory "
                    "(workspace-scoped).",
                    "enum": ["repo-local", "workspace-scoped"],
                    "type": "string",
                },
                "ownershipGuard": {
                    "default": "strict",
                    "description": "Strict refuses to operate on worktrees "
                    "owned by a different clone; advisory only "
                    "warns.",
                    "enum": ["strict", "advisory"],
                    "type": "string",
                },
                "rootDir": {
                    "description": "Filesystem directory containing the worktrees. "
                    "Supports `~` expansion. Defaults to "
                    "~/.ai-sdlc/worktrees.",
                    "type": "string",
                },
                "staleThresholdDays": {
                    "default": 14,
                    "description": "Worktrees older than this and not "
                    "associated with an active pipeline run "
                    "are eligible for reclamation.",
                    "minimum": 1,
                    "type": "integer",
                },
                "subscriptionPlans": {
                    "description": "References to SubscriptionPlan resources "
                    "by name (RFC-0010 §6.6).",
                    "items": {"type": "string"},
                    "type": "array",
                },
            },
            "type": "object",
        },
    },
    "required": ["apiVersion", "kind", "metadata", "spec"],
    "title": "AI-SDLC WorktreePool",
    "type": "object",
}

